import{c as i,Q as s,j as a,m as t}from"./chunks/framework.DoOjWOm2.js";const c=JSON.parse('{"title":"Hub-Admin: Federation Policy","description":"","frontmatter":{},"headers":[],"relativePath":"hub-admin/federation-policy.md","filePath":"hub-admin/federation-policy.md"}'),n={name:"hub-admin/federation-policy.md"};function r(o,e,l,h,u,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="hub-admin-federation-policy" tabindex="-1">Hub-Admin: Federation Policy <a class="header-anchor" href="#hub-admin-federation-policy" aria-label="Permalink to &quot;Hub-Admin: Federation Policy&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>A single Phlix Hub instance handles up to ~5000 users and ~200 servers — sufficient for the vast majority of deployments. Hub-to-hub federation (where two independent hub instances share users, servers, or libraries across trust boundaries) is intentionally not implemented in v1. Library sharing, server claiming, and relay all work within a single hub. Future federation (hub-to-hub API, cross-hub JWT auth, federated server metadata) is planned but not yet built. Operators needing multi-hub federation should track the roadmap; operators choosing a single-hub deployment get a fully functional system.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Federation API — future endpoints (NOT YET AVAILABLE in v1)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GET /api/v1/hubs/{hub-id}/servers         # list servers on a specific hub</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GET /api/v1/hubs/{hub-id}/users          # list users on a specific hub</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># POST /api/v1/federation/peers           # announce this hub as a federation peer</span></span></code></pre></div><blockquote><p><strong>Note:</strong> Federation endpoints above are design notes for future planning, not implemented features. Do not attempt to call them against a v1 hub.</p></blockquote><hr><h2 id="v1-single-hub-decision" tabindex="-1">v1 Single-Hub Decision <a class="header-anchor" href="#v1-single-hub-decision" aria-label="Permalink to &quot;v1 Single-Hub Decision&quot;">​</a></h2><h3 id="what-v1-delivers" tabindex="-1">What v1 Delivers <a class="header-anchor" href="#what-v1-delivers" aria-label="Permalink to &quot;What v1 Delivers&quot;">​</a></h3><p>A single Phlix Hub instance handles:</p><ul><li>Up to ~5000 user accounts</li><li>Up to ~200 claimed servers</li><li>Library sharing within the same hub instance</li><li>Server relay and streaming through the hub</li></ul><h3 id="what-v1-explicitly-does-not-include" tabindex="-1">What v1 Explicitly Does Not Include <a class="header-anchor" href="#what-v1-explicitly-does-not-include" aria-label="Permalink to &quot;What v1 Explicitly Does Not Include&quot;">​</a></h3><ul><li>Hub-to-hub communication (federation)</li><li>Cross-hub library sharing</li><li>Automatic peer discovery between hubs</li><li>Shared JWT/SSO across multiple hub instances</li></ul><h3 id="why-single-hub-was-chosen-for-v1" tabindex="-1">Why Single-Hub Was Chosen for v1 <a class="header-anchor" href="#why-single-hub-was-chosen-for-v1" aria-label="Permalink to &quot;Why Single-Hub Was Chosen for v1&quot;">​</a></h3><ol><li><strong>Simplicity:</strong> No trust model, NAT traversal, or cross-hub identity complexity</li><li><strong>Sufficiency:</strong> ~5000 users and ~200 servers cover the vast majority of deployments</li><li><strong>Industry precedent:</strong> Jellyfin and Emby — the closest analogs — do not implement true federation either; this is an unsolved problem in personal media serving</li><li><strong>Clear migration path:</strong> When scaling beyond a single hub is needed, the migration path is well-defined</li></ol><h3 id="what-this-means-for-users" tabindex="-1">What This Means for Users <a class="header-anchor" href="#what-this-means-for-users" aria-label="Permalink to &quot;What This Means for Users&quot;">​</a></h3><ul><li>Each user account lives on one hub — there is no cross-hub login</li><li>A server can only be claimed to one hub at a time — first claim wins</li><li>Library sharing only works within the same hub instance — shared libraries are not visible on other hubs</li><li>If you have accounts on two separate hubs, they are independent — no automatic synchronization</li></ul><h3 id="what-this-means-for-operators" tabindex="-1">What This Means for Operators <a class="header-anchor" href="#what-this-means-for-operators" aria-label="Permalink to &quot;What This Means for Operators&quot;">​</a></h3><ul><li>Multiple independent hub instances do not know about each other</li><li>Each hub operator manages their own users, servers, and content policies</li><li>There is no automatic peering with unknown hubs</li><li>Cross-hub collaboration requires manual account linking (see §Manual Federation)</li></ul><hr><h2 id="future-federation-design-roadmap-—-not-yet-implemented" tabindex="-1">Future Federation Design (Roadmap — Not Yet Implemented) <a class="header-anchor" href="#future-federation-design-roadmap-—-not-yet-implemented" aria-label="Permalink to &quot;Future Federation Design (Roadmap — Not Yet Implemented)&quot;">​</a></h2><blockquote><p>⚠️ This section describes a future design for when federation is needed. None of this is implemented in v1. Treat as planning reference only.</p></blockquote><h3 id="hub-to-hub-api" tabindex="-1">Hub-to-Hub API <a class="header-anchor" href="#hub-to-hub-api" aria-label="Permalink to &quot;Hub-to-Hub API&quot;">​</a></h3><p>If/when federation is added, the hub-to-hub API would expose:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/hubs/{hub-id}/servers    # list servers registered on a specific hub</span></span>
<span class="line"><span>GET /api/v1/hubs/{hub-id}/users      # list user accounts on a specific hub</span></span>
<span class="line"><span>GET /api/v1/hubs/{hub-id}/libraries  # list shared libraries on a specific hub</span></span></code></pre></div><p>These endpoints would be authenticated via mutual TLS or a pre-shared federation key.</p><h3 id="cross-hub-user-auth" tabindex="-1">Cross-Hub User Auth <a class="header-anchor" href="#cross-hub-user-auth" aria-label="Permalink to &quot;Cross-Hub User Auth&quot;">​</a></h3><p>Instead of each hub issuing its own JWTs with no cross-hub validity, a federated auth model would:</p><ul><li>Accept JWTs issued by other trusted hubs</li><li>Maintain a shared JWKS list of all federation peers&#39; public keys</li><li>Allow a user on Hub A to access resources on Hub B without creating a new Hub B account</li></ul><h3 id="federation-protocol" tabindex="-1">Federation Protocol <a class="header-anchor" href="#federation-protocol" aria-label="Permalink to &quot;Federation Protocol&quot;">​</a></h3><p>A hub announces itself as a federation peer by:</p><ol><li>Publishing its public key to a shared JWKS endpoint</li><li>Exchanging server metadata with known peers</li><li>Periodically updating its presence in the peer registry</li></ol><p>Federation peers exchange:</p><ul><li>Server metadata (hostname, library descriptions, server capabilities)</li><li>User identity assertions (verifying a user exists on Hub A without revealing their personal data)</li><li>Content policy declarations (what type of content a hub allows/rejects)</li></ul><h3 id="federation-challenges" tabindex="-1">Federation Challenges <a class="header-anchor" href="#federation-challenges" aria-label="Permalink to &quot;Federation Challenges&quot;">​</a></h3><p>The following challenges make federation non-trivial and are the reason it was deferred past v1:</p><table tabindex="0"><thead><tr><th>Challenge</th><th>Description</th></tr></thead><tbody><tr><td><strong>NAT traversal</strong></td><td>Servers behind NAT cannot be directly addressed by peers — requires relay or hole-punching</td></tr><tr><td><strong>Trust model</strong></td><td>Each hub must decide which other hubs are trusted; trust is not transitive</td></tr><tr><td><strong>User identity across hubs</strong></td><td>A user on Hub A is not the same entity as a user on Hub B — no shared identity layer</td></tr><tr><td><strong>Data privacy between operators</strong></td><td>Hub operators may have different privacy policies; federation must not leak user data across trust boundaries</td></tr><tr><td><strong>Content policy heterogeneity</strong></td><td>One hub may allow adult content; another may not — cross-hub sharing raises content policy conflicts</td></tr><tr><td><strong>No industry standard</strong></td><td>Jellyfin, Emby, Plex, and other media servers have not solved true federation — there is no spec to follow</td></tr></tbody></table><hr><h2 id="inter-hub-policy-even-for-v1-single-hub" tabindex="-1">Inter-Hub Policy (Even for v1 Single-Hub) <a class="header-anchor" href="#inter-hub-policy-even-for-v1-single-hub" aria-label="Permalink to &quot;Inter-Hub Policy (Even for v1 Single-Hub)&quot;">​</a></h2><p>Even though v1 does not implement federation, hub operators should be aware of the following inter-hub policy expectations:</p><h3 id="publishing-your-hub-url-and-terms-of-service" tabindex="-1">Publishing Your Hub URL and Terms of Service <a class="header-anchor" href="#publishing-your-hub-url-and-terms-of-service" aria-label="Permalink to &quot;Publishing Your Hub URL and Terms of Service&quot;">​</a></h3><p>Hub operators should publish:</p><ul><li>The public URL of their hub (e.g., <code>https://hub.example.com</code>)</li><li>A terms of service document covering content policy, acceptable use, and DMCA procedures</li><li>A privacy policy covering what user data the hub collects and how it is handled</li></ul><p>This is a prerequisite for any future federation participation.</p><h3 id="no-automatic-peering-with-unknown-hubs" tabindex="-1">No Automatic Peering with Unknown Hubs <a class="header-anchor" href="#no-automatic-peering-with-unknown-hubs" aria-label="Permalink to &quot;No Automatic Peering with Unknown Hubs&quot;">​</a></h3><p>v1 hubs do not automatically discover or peer with other hubs. A hub operator must explicitly configure federation peers. Unknown hubs cannot:</p><ul><li>Query your hub&#39;s server list</li><li>Authenticate users against your hub</li><li>Access your hub&#39;s library metadata</li></ul><h3 id="manual-federation-oauth-like-account-linking" tabindex="-1">Manual Federation: OAuth-like Account Linking <a class="header-anchor" href="#manual-federation-oauth-like-account-linking" aria-label="Permalink to &quot;Manual Federation: OAuth-like Account Linking&quot;">​</a></h3><p>The only cross-hub interaction available in v1 is manual account linking, similar to OAuth trust:</p><ol><li>User on Hub A wants to access resources on Hub B</li><li>Hub A issues a cross-hub identity token for that specific user</li><li>User presents the token to Hub B</li><li>Hub B validates the token against Hub A&#39;s public key</li><li>Hub B creates a shadow account for the user (mapped to their Hub A identity) with scoped access</li></ol><p>This is not true federation — it is a bilateral manual trust agreement between two specific hub operators.</p><h3 id="content-policy" tabindex="-1">Content Policy <a class="header-anchor" href="#content-policy" aria-label="Permalink to &quot;Content Policy&quot;">​</a></h3><p>Each hub operator sets their own rules about what content can be served from their hub. There is no cross-hub content policy enforcement. If Hub A serves content that Hub B&#39;s operator considers objectionable, Hub B can:</p><ul><li>Block access from Hub A&#39;s users to Hub B&#39;s servers</li><li>Decline to federate with Hub A at all</li><li>File a DMCA or abuse complaint with Hub A&#39;s operator</li></ul><hr><h2 id="migration-path-from-single-to-multi-hub" tabindex="-1">Migration Path: From Single to Multi-Hub <a class="header-anchor" href="#migration-path-from-single-to-multi-hub" aria-label="Permalink to &quot;Migration Path: From Single to Multi-Hub&quot;">​</a></h2><p>If a hub grows beyond the v1 single-hub capacity (~5000 users, ~200 servers), the migration path to multi-hub is:</p><h3 id="step-1-identify-the-split-point" tabindex="-1">Step 1: Identify the Split Point <a class="header-anchor" href="#step-1-identify-the-split-point" aria-label="Permalink to &quot;Step 1: Identify the Split Point&quot;">​</a></h3><p>Determine whether the split is:</p><ul><li><strong>Geographic:</strong> users in different regions (e.g., US East vs. EU West)</li><li><strong>Organizational:</strong> different tenant groups that need isolation</li><li><strong>Scale-based:</strong> pure capacity overflow</li></ul><h3 id="step-2-export-user-accounts" tabindex="-1">Step 2: Export User Accounts <a class="header-anchor" href="#step-2-export-user-accounts" aria-label="Permalink to &quot;Step 2: Export User Accounts&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export all user accounts from the source hub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-export.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export all server claims</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> servers-export.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export all library sharing grants</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share:export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shares-export.json</span></span></code></pre></div><h3 id="step-3-import-into-new-hub-instances" tabindex="-1">Step 3: Import into New Hub Instances <a class="header-anchor" href="#step-3-import-into-new-hub-instances" aria-label="Permalink to &quot;Step 3: Import into New Hub Instances&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create Hub A (e.g., US East) and import users</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us-east</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-export.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create Hub B (e.g., EU West) for the second region</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eu-west</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-export.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Filter imports by region during import (e.g., only EU users to EU hub)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/hub.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eu-west</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-export.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter-region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eu</span></span></code></pre></div><h3 id="step-4-server-reassignment" tabindex="-1">Step 4: Server Reassignment <a class="header-anchor" href="#step-4-server-reassignment" aria-label="Permalink to &quot;Step 4: Server Reassignment&quot;">​</a></h3><p>Servers must be re-claimed to the new hub:</p><ol><li>Server owner logs into the new hub</li><li>Server owner runs the claim flow against the new hub</li><li>Old hub releases the server claim (automatic after re-claim to new hub)</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the server, claim to the new hub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/phlix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hub:claim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://eu-west.hub.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-hub-toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="step-5-verify-library-access" tabindex="-1">Step 5: Verify Library Access <a class="header-anchor" href="#step-5-verify-library-access" aria-label="Permalink to &quot;Step 5: Verify Library Access&quot;">​</a></h3><p>After migration:</p><ul><li>Users on Hub A cannot see Hub B&#39;s libraries (and vice versa)</li><li>Shared library grants do not cross hub boundaries — re-establish shares if needed</li><li>Cross-hub access requires federation (future work) or manual account linking</li></ul><hr><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="user-expects-cross-hub-library-sharing-not-available-in-v1" tabindex="-1">User Expects Cross-Hub Library Sharing (not available in v1) <a class="header-anchor" href="#user-expects-cross-hub-library-sharing-not-available-in-v1" aria-label="Permalink to &quot;User Expects Cross-Hub Library Sharing (not available in v1)&quot;">​</a></h3><p><strong>Symptom:</strong> User on Hub A expects to see libraries shared by their friend on Hub B, but no cross-hub sharing is visible.</p><p><strong>Cause:</strong> Library sharing in v1 only works within the same hub instance. Cross-hub sharing requires federation, which is not yet implemented.</p><p><strong>Fix:</strong> Check whether both users are on the same hub (compare hub URLs in the dashboard). If on different hubs, explain that cross-hub sharing is not yet available. Direct users to the federation roadmap and the manual account linking option.</p><h3 id="hub-operator-assumes-federation-exists-it-does-not" tabindex="-1">Hub Operator Assumes Federation Exists (it does not) <a class="header-anchor" href="#hub-operator-assumes-federation-exists-it-does-not" aria-label="Permalink to &quot;Hub Operator Assumes Federation Exists (it does not)&quot;">​</a></h3><p><strong>Symptom:</strong> Hub operator sets up two independent hub instances expecting them to share users and servers automatically.</p><p><strong>Cause:</strong> v1 does not implement any federation. Each hub is fully independent with no shared state.</p><p><strong>Fix:</strong> Review this doc to understand v1&#39;s single-hub scope. If cross-hub collaboration is needed, consider: (a) consolidating to a single hub if under the ~5000 user / ~200 server limit, or (b) using the manual account linking approach for specific cross-hub use cases. Track the federation roadmap for future multi-hub support.</p><h3 id="server-owner-tries-to-claim-to-two-hubs-simultaneously-first-claim-wins" tabindex="-1">Server Owner Tries to Claim to Two Hubs Simultaneously (first claim wins) <a class="header-anchor" href="#server-owner-tries-to-claim-to-two-hubs-simultaneously-first-claim-wins" aria-label="Permalink to &quot;Server Owner Tries to Claim to Two Hubs Simultaneously (first claim wins)&quot;">​</a></h3><p><strong>Symptom:</strong> Server owner attempts to claim the same server to a second hub and gets an error, or discovers the server is registered to a different hub than expected.</p><p><strong>Cause:</strong> A server can only be claimed to one hub at a time. The first hub to receive and persist the claim owns the server relationship. Subsequent claims to other hubs are rejected.</p><p><strong>Fix:</strong> If the server was claimed to the wrong hub unintentionally:</p><ol><li>Contact the hub operator of the hub that currently holds the claim</li><li>Request that the hub operator release the server claim: <code>php bin/hub.php server:release &lt;server-id&gt;</code></li><li>Once released, claim the server to the correct hub: <code>php bin/phlix hub:claim --hub https://correct-hub.example.com</code></li></ol><p>Note: Releasing a server claim does not delete any media or data on the server — it only removes the relay association with the hub.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./hub-admin/overview.html">Hub-admin overview</a> — hub dashboard and admin CLI reference</li><li><a href="./hub-claim.html">Hub claim and setup</a> — understanding server claiming and hub identity</li><li><a href="./hub-shared-libraries.html">Hub shared libraries</a> — how shared libraries work within a single hub</li><li><a href="./hub-admin/abuse-handling.html">Hub-admin abuse handling</a> — DMCA workflow, GDPR data handling, audit log review</li></ul>`,89)])])}const b=i(n,[["render",r]]);export{c as __pageData,b as default};
